// Aggregate Health Status across all 3 software services
const hrStatus = $items('Check HR Portal (Port 8005)')[0]?.json ? '🟢 UP (200 OK)' : '🔴 DOWN';
const ragStatus = $items('Check RAG KMS (Port 8000)')[0]?.json ? '🟢 UP (200 OK)' : '🔴 DOWN';
const n8nStatus = $items('Check n8n Engine (Port 5678)')[0]?.json ? '🟢 UP (200 OK)' : '🔴 DOWN';

let rawMetrics = {};
try {
  rawMetrics = JSON.parse($items('Fetch EC2 RAM & Disk Metrics')[0]?.json?.stdout || '{}');
} catch(e) {}

const isAllHealthy = (hrStatus.includes('UP') && ragStatus.includes('UP') && n8nStatus.includes('UP'));
const statusSummary = isAllHealthy ? '🟢 ALL SYSTEMS OPERATIONAL' : '⚠️ WARNING: ONE OR MORE SERVICES DOWN';

const emailHtml = `
<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; border: 1px solid #e2e8f0; border-radius: 12px; overflow: hidden;">
  <div style="background-color: ${isAllHealthy ? '#0f766e' : '#b91c1c'}; color: white; padding: 20px; text-align: center;">
    <h2 style="margin: 0;">🖥️ RIS EC2 Daily System Health Report</h2>
    <p style="margin: 5px 0 0 0; font-weight: bold;">${statusSummary}</p>
  </div>
  <div style="padding: 24px; background-color: #f8fafc;">
    <h3 style="color: #1e293b; border-bottom: 2px solid #cbd5e1; padding-bottom: 8px;">📡 Active Software Services</h3>
    <table style="width: 100%; border-collapse: collapse;">
      <tr><td style="padding: 8px 0; font-weight: bold;">1. HR Career Portal (Port 8005):</td><td style="text-align: right;">${hrStatus}</td></tr>
      <tr><td style="padding: 8px 0; font-weight: bold;">2. KMS RAG System (Port 8000):</td><td style="text-align: right;">${ragStatus}</td></tr>
      <tr><td style="padding: 8px 0; font-weight: bold;">3. n8n Automation Engine (Port 5678):</td><td style="text-align: right;">${n8nStatus}</td></tr>
    </table>
    <h3 style="color: #1e293b; border-bottom: 2px solid #cbd5e1; padding-bottom: 8px; margin-top: 24px;">💾 EC2 Hardware & Memory Metrics</h3>
    <table style="width: 100%; border-collapse: collapse;">
      <tr><td style="padding: 8px 0; font-weight: bold;">Disk Space Usage:</td><td style="text-align: right;">${rawMetrics.disk_used_percent || 'N/A'}% (${rawMetrics.free_gb || 'N/A'} GB Free)</td></tr>
      <tr><td style="padding: 8px 0; font-weight: bold;">RAM Usage:</td><td style="text-align: right;">${rawMetrics.ram_used_percent || 'N/A'}% (${rawMetrics.ram_free_mb || 'N/A'} MB Free)</td></tr>
    </table>
  </div>
  <div style="background-color: #e2e8f0; text-align: center; padding: 12px; font-size: 0.85rem; color: #64748b;">
    Automated System Health Monitoring • RIS Server Infrastructure
  </div>
</div>
`;

return [{
  json: {
    subject: `[System Health] ${statusSummary} - EC2 Server (${new Date().toLocaleDateString()})`,
    emailHtml,
    isAllHealthy
  }
}];
